// @ts-check
/**
 * FEA-1791 / PLN-886 Phase 2 — the embedded migrations manifest generator.
 *
 * Reads migration.sql files from prisma/migrations in migration order and
 * writes src/main/database/migration/migrations-manifest.ts: an ordered array
 * of { name, checksum, sql }. New migrations use <YYYYMMDDHHMMSS>_<name>
 * (`date -u +%Y%m%d%H%M%S`); ISS-10416 retired the contiguous 000N scheme and
 * `migration-order.mjs` owns the rule and the boundary. Every committed name,
 * 000N and timestamped alike, is immutable and ordered at its original slot —
 * including the FEA-2030 one that predates the scheme, which is remapped by
 * `legacyMigrationSortKeys`. The runtime migration runner consumes this instead of reading
 * the filesystem, so migrations survive tarball staging into the packaged asar
 * (mirrors the build-info.ts prebuild + gitignore precedent).
 *
 * Regenerated by `pnpm prebuild` ahead of build / typecheck / test. The output
 * is gitignored. Checksums are sha256 of the raw migration.sql bytes; the
 * runner compares them against the recorded checksum to detect drift.
 *
 * ISS-5303 moved the body here out of scripts/generate-migrations-manifest.mjs,
 * which is now a shell that resolves the real desktop paths off
 * `import.meta.url` and calls `generateMigrationsManifest`. Every decision the
 * generator makes lives in this module — the legacy-manifest heal, the
 * empty-directory refusal, the symlink and path-escape rejections, the
 * checksum, the render and the write-if-changed branch — so
 * test/migrations-manifest-lib.test.ts can drive them against temp fixtures
 * instead of the real checkout. Behaviour and the emitted bytes are unchanged.
 */
import { createHash } from "node:crypto";
import {
  existsSync,
  lstatSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import { compareMigrationDirNames } from "./migration-order.mjs";

const MIGRATION_SQL_FILENAME = "migration.sql";

/**
 * Default sink for the generator's progress/diagnostic lines. Injectable so a
 * test can read what the generator reported instead of scraping stdout.
 *
 * @param {string} line
 */
function writeStdout(line) {
  process.stdout.write(line);
}

/**
 * The pre-ISS-5185 location of the generated manifest.
 *
 * Deliberately NOT the current output path: this is the file the heal below
 * deletes, so pointing it at the live manifest would delete the artifact the
 * build just produced.
 *
 * @param {string} appDir
 * @returns {string}
 */
export function legacyManifestPath(appDir) {
  return path.join(appDir, "src", "main", "database", "migrations-manifest.ts");
}

/**
 * ISS-5185 moved the generated manifest from database/ into database/migration/.
 * The old output is gitignored, so an existing checkout that already ran
 * `pnpm prebuild` still has the stale database/migrations-manifest.ts on disk —
 * it is inside tsconfig's `src` program glob and its `./migration-runner.js`
 * import no longer resolves, so typecheck fails after updating. Delete it here
 * so prebuild heals the checkout. Best-effort: a missing file is the normal
 * case on a fresh checkout and must not fail the build. Keep this until the
 * transition window closes.
 *
 * @param {string} appDir
 * @param {(line: string) => void} [writeLine]
 * @returns {void}
 */
export function healLegacyManifest(appDir, writeLine = writeStdout) {
  const legacyOutFile = legacyManifestPath(appDir);
  try {
    rmSync(legacyOutFile, { force: true });
  } catch (error) {
    writeLine(
      `generate-migrations-manifest: could not remove legacy ${path.relative(appDir, legacyOutFile)} (${error instanceof Error ? error.message : String(error)})\n`
    );
  }
}

/**
 * The migration directory names under `migrationsDir`, in migration order.
 *
 * An empty result is a broken checkout or a mis-resolved path, never a valid
 * state — emitting an empty manifest would ship an app that silently skips
 * every migration — so it throws rather than writing one.
 *
 * @param {string} migrationsDir
 * @returns {string[]}
 */
export function readMigrationDirNames(migrationsDir) {
  const migrationDirs = readdirSync(migrationsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort(compareMigrationDirNames);

  if (migrationDirs.length === 0) {
    throw new Error(
      `generate-migrations-manifest: no migrations found in ${migrationsDir}`
    );
  }

  return migrationDirs;
}

/**
 * Read and checksum each migration's SQL, rejecting anything that is not a
 * regular file checked into the migrations directory.
 *
 * @param {readonly string[]} migrationDirNames
 * @param {{ appDir: string, migrationsDir: string }} paths
 * @returns {{ name: string, checksum: string, sql: string }[]}
 */
export function buildMigrationEntries(migrationDirNames, paths) {
  const { appDir, migrationsDir } = paths;
  const migrationsRoot = realpathSync(migrationsDir);

  return migrationDirNames.map((name) => {
    const sqlPath = path.join(migrationsDir, name, MIGRATION_SQL_FILENAME);
    // Reject symlinked migration files and any file whose realpath escapes the
    // migrations directory — the embedded SQL runs at app boot, so it must come
    // only from a regular file checked into prisma/migrations.
    const stat = lstatSync(sqlPath);
    if (!stat.isFile() || stat.isSymbolicLink()) {
      throw new Error(
        `generate-migrations-manifest: ${path.relative(appDir, sqlPath)} must be a regular, non-symlink file`
      );
    }
    const realSqlPath = realpathSync(sqlPath);
    const relativeToRoot = path.relative(migrationsRoot, realSqlPath);
    if (relativeToRoot.startsWith("..") || path.isAbsolute(relativeToRoot)) {
      throw new Error(
        `generate-migrations-manifest: ${path.relative(appDir, sqlPath)} resolves outside ${path.relative(appDir, migrationsDir)}`
      );
    }
    const sql = readFileSync(realSqlPath, "utf8");
    const checksum = createHash("sha256").update(sql, "utf8").digest("hex");
    return { name, checksum, sql };
  });
}

/**
 * Render the generated TypeScript module for an ordered entry list.
 *
 * @param {readonly { name: string, checksum: string, sql: string }[]} entries
 * @returns {string}
 */
export function renderManifest(entries) {
  const body = entries
    .map(
      (entry) =>
        `  {\n    name: ${JSON.stringify(entry.name)},\n    checksum: ${JSON.stringify(
          entry.checksum
        )},\n    sql: ${JSON.stringify(entry.sql)},\n  },`
    )
    .join("\n");

  return `// AUTO-GENERATED by scripts/generate-migrations-manifest.mjs — do not edit.
// FEA-1791 / PLN-886 Phase 2: ordered embedded migrations for the desktop
// SQLite runtime migration runner. Regenerated by \`pnpm prebuild\`.
import type { EmbeddedMigration } from "./migration-runner.js";

export const MIGRATIONS: readonly EmbeddedMigration[] = [
${body}
];
`;
}

/**
 * Write the manifest only when its bytes changed, so a no-op prebuild does not
 * touch the file's mtime and invalidate downstream build caches.
 *
 * @param {{
 *   appDir: string,
 *   outFile: string,
 *   contents: string,
 *   migrationCount: number,
 *   writeLine?: (line: string) => void,
 * }} options
 * @returns {boolean} Whether the file was written.
 */
export function writeManifestIfChanged(options) {
  const {
    appDir,
    outFile,
    contents,
    migrationCount,
    writeLine = writeStdout,
  } = options;

  if (existsSync(outFile) && readFileSync(outFile, "utf8") === contents) {
    writeLine(
      `generate-migrations-manifest: unchanged (${migrationCount} migration(s))\n`
    );
    return false;
  }

  writeFileSync(outFile, contents, "utf8");
  writeLine(
    `generate-migrations-manifest: wrote ${migrationCount} migration(s) to ${path.relative(appDir, outFile)}\n`
  );
  return true;
}

/**
 * Heal the legacy output, read and validate the migrations, and write the
 * manifest if it changed.
 *
 * @param {{
 *   appDir: string,
 *   migrationsDir: string,
 *   outFile: string,
 *   writeLine?: (line: string) => void,
 * }} options
 * @returns {{
 *   entries: { name: string, checksum: string, sql: string }[],
 *   contents: string,
 *   wrote: boolean,
 * }}
 */
export function generateMigrationsManifest(options) {
  const { appDir, migrationsDir, outFile, writeLine = writeStdout } = options;

  healLegacyManifest(appDir, writeLine);

  const entries = buildMigrationEntries(readMigrationDirNames(migrationsDir), {
    appDir,
    migrationsDir,
  });
  const contents = renderManifest(entries);
  const wrote = writeManifestIfChanged({
    appDir,
    outFile,
    contents,
    migrationCount: entries.length,
    writeLine,
  });

  return { entries, contents, wrote };
}

// @ts-check

export const legacyMigrationSortKeys = new Map([
  ["0011_session_activity_segments", "0011_session_activity_segments"],
  [
    "20260619220000_add_genai_prices_pricing_source",
    "0004_add_genai_prices_pricing_source",
  ],
  // FEA-2267 (#2157) merged with a stale base and re-used the 0011 prefix
  // already taken by 0011_clear_default_branch_pr_poison (which landed first),
  // producing two committed `0011_` migrations on main. Both are immutable, so
  // neither can be renamed. clear_default_branch_pr_poison keeps slot 0011 (it
  // landed first); session_activity_segments is logically the 12th migration,
  // so map it to a 0012 sort key. This exempts it from the canonical-name check
  // and orders it after 0011_clear — matching the existing application order
  // ("clear" < "session"), so runtime migration order is unchanged.
  ["0011_session_activity_segments", "0012_session_activity_segments"],
]);

/**
 * ISS-10416. The LAST desktop migration committed under the historical
 * contiguous `000N_` scheme. Everything at or before it keeps the name it
 * merged with; everything after it is named `YYYYMMDDHHMMSS_<snake_case>`.
 *
 * This constant IS the boundary between the two schemes — the one place it is
 * stated, so neither the guard nor the docs infers it from the directory list.
 *
 * Why the scheme changed: a contiguous prefix is a property of the MERGED tree,
 * not of a PR, so two PRs cut from the same base both pick the same next number
 * and whichever merges second reddens the merge group. On 2026-09-16 that
 * ejected seven merge groups from three PRs, and 13 desktop migrations merged
 * in the preceding seven days, so two concurrent migration PRs is the common
 * case.
 *
 * What a UTC timestamp buys, stated exactly, because the overclaim is easy to
 * write: two branches can never CLAIM THE SAME SLOT, so no PR is ever renumbered
 * because someone else took its number, and nothing cascades to the PRs behind
 * it. It does NOT make every merge order free. `findOutOfOrderMigrations`
 * (`scripts/lint/check-destructive-migrations.ts`) still refuses a new migration
 * sorting below the tip on `main`, so of two same-base PRs the one that MINTED
 * EARLIER must also MERGE earlier; minted-earlier-merging-second re-mints its
 * own timestamp once, against a tip that is not moving under it. That refusal is
 * load-bearing, not incidental — a build shipped between the two merges leaves
 * stores with the later migration applied, and the earlier one slotting in
 * behind it is the runner's `HistoryGap`. Pinned in
 * `scripts/lint/desktop-migration-same-base-pair.test.ts`.
 *
 * Why the history is NOT renamed: the runner keys `_desktop_migrations` on the
 * directory NAME (`src/main/database/migration/migration-runner.ts`), so a
 * rename reads back on an already-migrated store as a name the bundle does not
 * ship and refuses the boot with `MigrationRefusalKind.Downgrade`.
 *
 * Why a fixed name here is not the old trap wearing a new label: the rule it
 * feeds is "sorts after THIS name ⇒ must be timestamped", whose verdict for a
 * given branch does not change when somebody else's migration merges — unlike
 * "prefix equals the count of everything ahead of you", which changed with
 * every merge and is what ejected the groups. It is also self-freezing: the
 * only thing that could make this constant stale is a new `000N_` directory,
 * and that is precisely what the rule refuses.
 */
export const lastContiguousMigrationDirName =
  "0094_iss8617_session_outbox_engine_state";

/** `000N_snake_case` — the historical scheme, closed to new entries. */
const CONTIGUOUS_MIGRATION_DIR_RE = /^\d{4}_[a-z0-9][a-z0-9_]*$/;

/** `YYYYMMDDHHMMSS_snake_case` — the scheme every new migration uses. */
const TIMESTAMP_MIGRATION_DIR_RE = /^(\d{14})_[a-z0-9][a-z0-9_]*$/;

const TIMESTAMP_PARTS_RE = /^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})$/;

/**
 * The first year a minted prefix may carry — when the scheme starts. The past
 * side is the cheap one: a far-past prefix sorts below the tip and
 * `findOutOfOrderMigrations` already refuses it as backdated, so this only moves
 * the refusal to the naming gate, where the message names the real rule.
 */
const MIN_MIGRATION_YEAR = 2026;

/**
 * How far past the reading clock a prefix may sit. A prefix is minted with
 * `date -u` on the author's machine and read back on another one, so this covers
 * the skew between those two clocks and nothing else.
 */
const MAX_MINT_SKEW_MS = 24 * 60 * 60 * 1000;

/**
 * @param {string} left
 * @param {string} right
 */
export function compareMigrationDirNames(left, right) {
  const leftKey = migrationSortKey(left);
  const rightKey = migrationSortKey(right);
  return leftKey.localeCompare(rightKey) || left.localeCompare(right);
}

/**
 * @param {string} name
 */
export function migrationSortKey(name) {
  return legacyMigrationSortKeys.get(name) ?? name;
}

/**
 * Whether a 14-digit prefix is a real UTC instant that has already happened.
 *
 * Round-tripped through `Date` rather than range-checked field by field: that
 * rejects month 13, day 32, February 30, hour 24 and second 60 in one step, and
 * a bare digit count would accept every one of them as a migration sorting
 * wherever its digits happen to fall.
 *
 * THE FUTURE BOUND IS THE CLOCK, NOT A YEAR BAND. A future prefix is the one
 * typo nothing downstream catches: it sorts above everything, so it merges, and
 * a merged directory can never be renamed — from then on every correctly minted
 * migration sorts BELOW the tip and `findOutOfOrderMigrations` reports each one
 * as backdated with no legal remedy. A year ceiling only narrows the window a
 * typo can land in: `2926` is caught by a band, `2036` is the same single
 * keystroke and is not. `now` catches both, and every other future typo.
 *
 * Bounding by `now` is safe against the committed set precisely because `now`
 * only moves forward: a prefix that passed once keeps passing forever, so this
 * can never redden a directory that is already immutable. {@link
 * MAX_MINT_SKEW_MS} is the allowance for the mint clock and the reading clock
 * being different machines.
 *
 * @param {string} prefix
 */
function isUtcTimestampPrefix(prefix) {
  const parts = TIMESTAMP_PARTS_RE.exec(prefix);
  if (parts === null) {
    return false;
  }
  if (Number(parts[1]) < MIN_MIGRATION_YEAR) {
    return false;
  }
  const iso = `${parts[1]}-${parts[2]}-${parts[3]}T${parts[4]}:${parts[5]}:${parts[6]}.000Z`;
  const parsed = new Date(iso);
  if (Number.isNaN(parsed.getTime()) || parsed.toISOString() !== iso) {
    return false;
  }
  return parsed.getTime() <= Date.now() + MAX_MINT_SKEW_MS;
}

/**
 * @param {string} name
 */
function isTimestampMigrationDirName(name) {
  const match = TIMESTAMP_MIGRATION_DIR_RE.exec(name);
  return match !== null && isUtcTimestampPrefix(match[1] ?? "");
}

/**
 * The remedy sentence, so the guard, the docs and a failing CI log hand a new
 * author the same instruction.
 */
export function describeNewMigrationDirNameRule() {
  return (
    "run `date -u +%Y%m%d%H%M%S` and use its output as the prefix, e.g. " +
    "20260916231500_iss1234_add_widget_index. The contiguous 000N scheme ended " +
    `at ${lastContiguousMigrationDirName} (ISS-10416) because two PRs cut from ` +
    "the same base both pick the same next number and the second to merge " +
    "reddens the merge group. A committed directory is never renamed, which is " +
    "why a prefix in the FUTURE is refused too: it would sort above every " +
    "later mint and leave each one unfixably backdated."
  );
}

/**
 * Every naming or ordering violation in a set of desktop migration directory
 * names, as ready-to-print lines. Empty means the set is legal.
 *
 * Three rules, and the boundary decides which of the first two applies:
 *  1. at or before {@link lastContiguousMigrationDirName} a name is historical,
 *     so it keeps its `000N_` shape (or its {@link legacyMigrationSortKeys}
 *     entry) and is never re-checked for contiguity — the two committed `0011_`
 *     directories mean the history is not contiguous and cannot be made so;
 *  2. after the boundary a name must be `YYYYMMDDHHMMSS_snake_case`;
 *  3. sort keys strictly increase, so the applied set on an upgraded install
 *     stays a contiguous prefix of the bundle. Anything else is the runner's
 *     `HistoryGap` refusal.
 *
 * What this deliberately does NOT catch is a new migration BACKDATED behind the
 * branch it was cut from. That needs the base branch's directory list, which
 * only `scripts/lint/check-destructive-migrations.ts` has — its
 * `findOutOfOrderMigrations` sorts through this module's `migrationSortKey`.
 *
 * @param {readonly string[]} dirNames
 * @returns {string[]}
 */
export function findMigrationDirNameViolations(dirNames) {
  const sorted = [...dirNames].sort(compareMigrationDirNames);
  const boundaryKey = migrationSortKey(lastContiguousMigrationDirName);
  /** @type {string[]} */
  const violations = [];
  let previousName = "";
  let previousKey = "";
  for (const name of sorted) {
    const sortKey = migrationSortKey(name);
    if (previousName !== "" && sortKey <= previousKey) {
      violations.push(
        `Migration directory ${name} must sort after ${previousName}`
      );
    }
    previousName = name;
    previousKey = sortKey;

    if (sortKey <= boundaryKey) {
      if (
        !(
          legacyMigrationSortKeys.has(name) ||
          CONTIGUOUS_MIGRATION_DIR_RE.test(name)
        )
      ) {
        violations.push(
          `Migration directory ${name} sorts within the committed 000N history but is not one of its names`
        );
      }
      continue;
    }

    if (!isTimestampMigrationDirName(name)) {
      violations.push(
        `Migration directory ${name} must be named <YYYYMMDDHHMMSS>_<snake_case>: ${describeNewMigrationDirNameRule()}`
      );
    }
  }
  return violations;
}

// @ts-check
/**
 * ISS-11243 — the pure half of `generate-auth-handoff-assets.mjs`.
 *
 * The entrypoint writes `src/shared/auth-handoff-assets.generated.ts` at module
 * scope, so it cannot be imported by the node lane. Everything it derives lives
 * here: theme-block extraction, the data-URL encoding, and the rendered module
 * source. The design-system files are read through an injected reader so tests
 * can supply fixtures.
 */

export const DESIGN_SYSTEM_THEME_PATH = "styles/globals.css";
export const LOGO_LIGHT_PATH =
  "brand/logos/Horizontal/closedloop-logo-horizontal-on-light.svg";
export const LOGO_DARK_PATH =
  "brand/logos/Horizontal/closedloop-logo-horizontal-on-dark.svg";
export const FONT_PATH =
  "node_modules/geist/dist/fonts/geist-sans/Geist-Regular.woff2";
export const MISSING_THEME_MESSAGE =
  "Auth handoff could not load the design-system themes";

const LIGHT_THEME_RE = /:root\s*\{([\s\S]*?)\n\}/;
const DARK_THEME_RE = /\.dark\s*\{([\s\S]*?)\n\}/;

/**
 * @param {string} css
 * @returns {{ light: string, dark: string }}
 */
export function extractThemeBlocks(css) {
  const light = css.match(LIGHT_THEME_RE)?.[1];
  const dark = css.match(DARK_THEME_RE)?.[1];
  if (!(light && dark)) {
    throw new Error(MISSING_THEME_MESSAGE);
  }
  return { light, dark };
}

/**
 * @param {Uint8Array} bytes
 * @param {string} mime
 */
export function toDataUrl(bytes, mime) {
  return `data:${mime};base64,${Buffer.from(bytes).toString("base64")}`;
}

/**
 * The themes are read and checked before any binary asset, so a missing theme
 * block fails without touching the logos or the font.
 *
 * @param {(designSystemPath: string) => Buffer} readDesignSystemFile
 */
export function buildAuthHandoffAssets(readDesignSystemFile) {
  const { light, dark } = extractThemeBlocks(
    readDesignSystemFile(DESIGN_SYSTEM_THEME_PATH).toString("utf8")
  );
  return {
    theme: `:root {${light}\n}\n@media (prefers-color-scheme: dark) { :root {${dark}\n} }`,
    logoLight: toDataUrl(
      readDesignSystemFile(LOGO_LIGHT_PATH),
      "image/svg+xml"
    ),
    logoDark: toDataUrl(readDesignSystemFile(LOGO_DARK_PATH), "image/svg+xml"),
    font: toDataUrl(readDesignSystemFile(FONT_PATH), "font/woff2"),
  };
}

/**
 * @param {ReturnType<typeof buildAuthHandoffAssets>} assets
 */
export function renderAuthHandoffAssetsModule(assets) {
  return `// Generated by scripts/generate-auth-handoff-assets.mjs.\nexport const AUTH_HANDOFF_ASSETS = ${JSON.stringify(assets)};\n`;
}
